'use client';
import { useId, useState, type KeyboardEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Avatar, avatarInk, enter, Think, Tip, useGrow } from '../lib/motion';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './comments.css';

export interface CommentsPerson {
  name: string;
  /** Two letters for the avatar, like "MK" */
  initials: string;
  /** The avatar colour, like 'var(--dm-av-l)' */
  color: string;
  /** What follows the @ to mention them, like "maya". People with a handle show up in the mention menu */
  handle?: string;
}

export interface CommentsAction {
  label: string;
  /** Draws it as the accent button. The others are white with an outline */
  primary?: boolean;
  onClick: () => void;
}

export interface CommentsEntry {
  /** Keeps the comment in place when the list changes */
  id: string;
  author: CommentsPerson;
  /** The comment. A string gets its @mentions highlighted; an agent's reply fades in word by word as it grows */
  text: ReactNode;
  /** Like "2h" or "now" */
  time: string;
  /** Marks the agent's replies: their words fade in as `text` grows */
  agent?: boolean;
  /** Shows the thinking mark instead of the text while the agent works on a reply */
  thinking?: boolean;
  /** Buttons under the comment, like "Apply to all" */
  actions?: CommentsAction[];
  /** Replaces the buttons once one is used, like "Applied to 3 frames" */
  resolution?: string;
  /** How many other people agreed with it. Yours is added on top when you agree */
  agrees?: number;
}

export interface CommentsProps {
  /** What the thread is about, like "Pricing, frame 2" */
  title: string;
  /** The number on the pin, like 1 */
  pin?: ReactNode;
  /** The thread: the first comment starts it, and every later one is a reply, indented under it */
  comments: CommentsEntry[];
  /** Who can be @mentioned. Typing @ and the start of a handle opens a menu of them */
  people?: CommentsPerson[];
  /** The reply being written. Leave it out to let the field keep it */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called with the reply when it is sent. Add it to `comments` to show it */
  onSend?: (text: string) => void;
  placeholder?: string;
  /** Whether the thread is resolved: the pin turns green, a Resolved chip shows and the reply field folds away, while the
      thread keeps its colours. Leave it out to let the Resolve button toggle it */
  resolved?: boolean;
  defaultResolved?: boolean;
  onResolvedChange?: (resolved: boolean) => void;
  /** The ids of the comments you agreed with. Leave it out to let the Agree buttons keep it */
  agreed?: string[];
  defaultAgreed?: string[];
  onAgreedChange?: (ids: string[]) => void;
  className?: string;
}

/** Highlights @handles. With people given, only theirs; otherwise any @word */
function mentions(text: string, handles: string[] | null) {
  return text.split(/(@\w+)/).map((part, i) => {
    const hit = part.startsWith('@') && (!handles || handles.includes(part.slice(1).toLowerCase()));
    return hit ? <span key={i} className="dm-m">{part}</span> : part;
  });
}

function Comment({ c, handles, mine, onAgree }: { c: CommentsEntry; handles: string[] | null; mine: boolean; onAgree: () => void }) {
  const e = enter();
  let body: ReactNode = c.text;
  if (c.thinking) body = <Think />;
  else if (c.agent && typeof c.text === 'string') body = c.text.split(' ').map((w, i) => <span key={i} className="dm-w">{w} </span>);
  else if (typeof c.text === 'string') body = mentions(c.text, handles);
  const n = (c.agrees ?? 0) + (mine ? 1 : 0);
  return (
    <div className={cx('dm-cmx-c', c.agent && 'dm-ag', e.className)} style={e.style}>
      <Avatar initials={c.author.initials} color={c.author.color} />
      <div className="dm-b">
        <div className="dm-n">
          <b>{c.author.name}</b><span className="dm-t">{c.time}</span>
          {/* the quiet Agree button shows on hover or keyboard focus, and always on a touch screen */}
          <div className="dm-cmx-tools">
            <Tip label="Agree"><button type="button" className="dm-ib dm-cmx-rx" aria-label="Agree" aria-pressed={mine} onClick={onAgree}><Icon name="up-thumb" size="xs" /></button></Tip>
          </div>
        </div>
        <div className="dm-tx" style={c.thinking ? { color: 'var(--dm-accent-mark, var(--dm-accent))' } : undefined}>{body}</div>
        {n > 0 && (
          <div className="dm-cmx-rs">
            <button type="button" className="dm-cmx-rc" aria-pressed={mine} aria-label={'Agree, ' + n + (n === 1 ? ' person' : ' people') + (mine ? ', including you' : '')} onClick={onAgree}>
              <Icon name="up-thumb" size="xs" /><span className="dm-num">{n}</span>
            </button>
          </div>
        )}
        {(c.resolution || !!c.actions?.length) && (
          <div className={cx('dm-act', e.className)}>
            {c.resolution
              ? <span className="dm-cmx-rv dm-enter"><Icon name="ok" size="xs" />{c.resolution}</span>
              : c.actions!.map((a, i) => <button type="button" key={i} className={cx('dm-pill dm-sm', a.primary ? 'dm-primary' : 'dm-line')} onClick={a.onClick}>{a.label}</button>)}
          </div>
        )}
      </div>
    </div>
  );
}

/** A comment thread on a design, where you can @mention the agent and it replies. */
export function Comments({ title, pin = 1, comments, people, value, defaultValue = '', onValueChange, onSend, placeholder = 'Reply, or @agent to ask', resolved, defaultResolved = false, onResolvedChange, agreed, defaultAgreed = [], onAgreedChange, className }: CommentsProps) {
  const [draft, setDraft] = useControllable(value, defaultValue, onValueChange);
  const [done, setDone] = useControllable(resolved, defaultResolved, onResolvedChange);
  const [yes, setYes] = useControllable(agreed, defaultAgreed, onAgreedChange);
  const handles = people ? people.flatMap(p => (p.handle ? [p.handle.toLowerCase()] : [])) : null;
  const agree = (id: string) => setYes(yes.includes(id) ? yes.filter(x => x !== id) : [...yes, id]);

  // typing @ and the start of a handle offers the people it could be; Escape puts the menu away until the text changes
  const [dismissed, setDismissed] = useState<string | null>(null);
  const typed = draft.match(/@(\w*)$/);
  const matches = typed ? (people ?? []).filter(p => p.handle?.toLowerCase().startsWith(typed[1].toLowerCase())) : [];
  const menuOpen = matches.length > 0 && dismissed !== draft;
  const pick = (p: CommentsPerson) => setDraft(draft.replace(/@\w*$/, '@' + p.handle + ' '));
  // the highlighted person: the up and down arrows move it and wrap, and it starts on the first whenever the list changes
  const [hl, setHl] = useState({ at: 0, for: '' });
  const at = hl.for === draft ? Math.min(hl.at, matches.length - 1) : 0;
  const id = useId();

  const send = () => { const v = draft.trim(); if (!v) return; setDraft(''); onSend?.(v); };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    if (menuOpen && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) { e.preventDefault(); setHl({ at: (at + (e.key === 'ArrowDown' ? 1 : -1) + matches.length) % matches.length, for: draft }); return; }
    if (e.key === 'Enter') { e.preventDefault(); if (menuOpen) pick(matches[at]); else send(); }
    if (e.key === 'Escape') setDismissed(draft);
  };

  const [head, ...replies] = comments;
  const one = (c: CommentsEntry) => <Comment key={c.id} c={c} handles={handles} mine={yes.includes(c.id)} onAgree={() => agree(c.id)} />;
  // the thread keeps no room for replies to come: it eases taller as they arrive and as the agent's words stream in, and the
  // reply field under it glides down with it
  const [thRoot, thInner] = useGrow();

  return (
    <div data-dm="" className={cx('dm-cmx dm-panel', done && 'dm-done', className)}>
      <div className="dm-cmx-h">
        <span className="dm-cmx-pin" aria-hidden="true">{pin}</span>
        <b>{title}</b>
        {/* the head says nothing the thread already shows (no count of the replies); once resolved, a green chip says so */}
        <span className="dm-cmx-st">{done && <span className="dm-tag dm-ok dm-enter">Resolved</span>}</span>
        <Tip label={done ? 'Reopen thread' : 'Resolve thread'}>
          <button type="button" className="dm-ib dm-cmx-res" aria-label="Resolve thread" aria-pressed={done} onClick={() => setDone(!done)}>
            <Icon name={done ? 'undo' : 'check'} size="xs" />
          </button>
        </Tip>
      </div>
      <div ref={thRoot} className="dm-cmx-th dm-growing" aria-live="polite">
        <div ref={thInner} className="dm-grow">
          {head && one(head)}
          {replies.length > 0 && <div className="dm-cmx-rp" role="group" aria-label="Replies">{replies.map(one)}</div>}
        </div>
      </div>
      <div className="dm-cmx-in" inert={done}>
        <div className="dm-cmx-box">
          <input placeholder={placeholder} aria-label="Reply" spellCheck={false} autoComplete="off" value={draft} onChange={e => setDraft(e.target.value)} onKeyDown={key}
            role="combobox" aria-expanded={menuOpen} aria-autocomplete="list" aria-controls={`${id}-men`} aria-activedescendant={menuOpen ? `${id}-${at}` : undefined} />
          <button type="button" className="dm-cmx-go" aria-label="Send" disabled={!draft.trim()} onClick={send}><Icon name="up" size="xs" /></button>
        </div>
        <div className={cx('dm-pop dm-cmx-men', menuOpen && 'dm-open')} role="listbox" id={`${id}-men`} aria-label="Mention" inert={!menuOpen}>
          {matches.map((p, i) => (
            // mousedown, so the field keeps its focus
            <button type="button" key={p.handle} id={`${id}-${i}`} tabIndex={-1} className={cx('dm-mi', i === at && 'dm-hl')} role="option" aria-selected={i === at}
              onMouseEnter={() => setHl({ at: i, for: draft })} onMouseDown={e => { e.preventDefault(); pick(p); }}>
              <span className="dm-av" style={{ background: p.color, color: avatarInk(p.color), width: 20, height: 20, fontSize: 9 }} aria-hidden="true">{p.initials}</span>
              <span>{p.name}<span className="dm-d">@{p.handle}</span></span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Comments ---------- */
/* a thread on one spot of a design: the first comment, then its replies indented on a thin line. Each comment is an avatar,
   a name, a time and the text; its Agree button shows on hover or keyboard focus (always, on a touch screen). The card's
   content is 16px from every edge in every style, and it keeps no room for replies still to come: it grows as they arrive
   (grow()) and stays centred in its stage (owner, 17 and 18 Nov). Hovers are a quiet fill that shows in light mode too */
.dm-cmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
/* the head sits on the comments' columns: the pin centred in the avatars' 24px column, the title where their words start,
   and Resolve's glyph on the right edge the Send button ends on, its hover box reaching out round it */
.dm-cmx-h{display:flex;align-items:center;gap:var(--dm-s-3);min-height:20px;padding-bottom:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:20px}
.dm-cmx-h b{font-weight:500}
.dm-cmx-st{flex:1;min-width:0;display:flex}
.dm-cmx-pin{width:20px;height:20px;margin:0 2px;border-radius:50% 50% 50% var(--dm-r-xs);background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;font-size:11px;font-weight:500;flex:none;transition:background var(--dm-t)}
.dm-cmx.dm-done .dm-cmx-pin{background:var(--dm-ok);color:var(--dm-surface)}
.dm-cmx-res{width:28px;height:28px;margin:-4px -3px -4px 0;color:var(--dm-muted)}
.dm-cmx-th{--dm-cmx-ln:color-mix(in srgb,var(--dm-rail) 50%,var(--dm-surface));display:flex;flex-direction:column;gap:var(--dm-s-4);flex:1}
/* dark: the rail is close to the surface already, so the line keeps more of it to stay visible */
:root[data-theme="dark"] .dm-cmx-th{--dm-cmx-ln:color-mix(in srgb,var(--dm-rail) 80%,var(--dm-surface))}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-cmx-th{--dm-cmx-ln:color-mix(in srgb,var(--dm-rail) 80%,var(--dm-surface))}}
/* a reply's avatar starts where the words of the comment it answers start (12px + 24px in), so the thread keeps one column */
.dm-cmx-rp{--dm-cmx-x:calc(-1 * var(--dm-s-6) - .75px);display:flex;flex-direction:column;gap:var(--dm-s-4);margin-left:var(--dm-s-3);padding-left:var(--dm-s-6);position:relative}
/* one unbroken line (owner, 21 Nov: "these lines are not connected"): it starts just below the first comment's avatar,
   centred under it, and runs straight down to the last reply's branch, where it ends. Every piece of it is drawn the same
   way, a 1.5px left border at the same x, and each piece overlaps the next, so they meet with no seam */
:is(.dm-cmx-th,.dm-cmx-th>.dm-grow)>.dm-cmx-c:first-child{position:relative}
:is(.dm-cmx-th,.dm-cmx-th>.dm-grow)>.dm-cmx-c:first-child:has(+ .dm-cmx-rp)::before{content:'';position:absolute;width:0;border-left:1.5px solid var(--dm-cmx-ln);pointer-events:none;left:calc(var(--dm-s-3) - .75px);top:calc(24px + var(--dm-s-1));bottom:calc(-1 * var(--dm-s-4))}
/* each reply: a branch leaves the line and turns into its avatar's centre (rounded in Soft and Clean, square in Blueprint);
   under every reply but the last the line carries straight on past the branch, and as a reply arrives the line draws itself
   down to it */
.dm-cmx-rp>.dm-cmx-c{position:relative}
.dm-cmx-rp>.dm-cmx-c .dm-av{position:relative;z-index:1}
.dm-cmx-rp>.dm-cmx-c::before{content:'';position:absolute;left:var(--dm-cmx-x);top:calc(-1 * var(--dm-s-4));width:calc(var(--dm-s-6) + 1.75px);height:calc(var(--dm-s-4) + 12.75px);box-sizing:border-box;border-left:1.5px solid var(--dm-cmx-ln);border-bottom:1.5px solid var(--dm-cmx-ln);border-bottom-left-radius:10px;corner-shape:round;pointer-events:none}
.dm-cmx-rp>.dm-cmx-c:not(:last-child)::after{content:'';position:absolute;left:var(--dm-cmx-x);top:0;bottom:calc(-1 * var(--dm-s-4));width:0;border-left:1.5px solid var(--dm-cmx-ln);pointer-events:none;transform-origin:top;animation:dm-cmxrl var(--dm-t) var(--dm-ease) both}
@keyframes dm-cmxrl{from{transform:scaleY(0)}}
:root:not([data-style="soft"],[data-style="clean"]) .dm-cmx-rp>.dm-cmx-c:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{border-bottom-left-radius:0}
.dm-cmx-c{display:flex;gap:var(--dm-s-3);min-width:0}
.dm-cmx-c .dm-av{width:24px;height:24px;font-size:10px}
.dm-cmx-c .dm-b{flex:1;display:flex;flex-direction:column;min-width:0}
.dm-cmx-c .dm-n{display:flex;align-items:center;gap:var(--dm-s-2);height:24px;font-size:13px}
.dm-cmx-c .dm-n b{font-weight:500;white-space:nowrap}
.dm-cmx-c .dm-n .dm-t{font-size:12px;color:var(--dm-muted)}
.dm-cmx-c .dm-tx{font-size:13.5px;line-height:1.5;color:var(--dm-fg);overflow-wrap:anywhere}
/* an @mention: the accent's text on its tint, the tint reaching out round the word so the word stays on the text's column */
.dm-cmx-c .dm-m{color:var(--dm-accent-fg);background:var(--dm-sel);border-radius:var(--dm-r-xs);padding:0 2px;margin:0 -2px}
.dm-cmx-c.dm-ag .dm-tx .dm-w{animation:dm-cmw .4s var(--dm-ease) both}
@keyframes dm-cmw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
/* the agent's buttons wrap before they reach the column's right edge, so on a phone they never end a few pixels short of the
   edge Send and Resolve end on */
.dm-cmx-c .dm-act{display:flex;flex-wrap:wrap;gap:var(--dm-s-2);margin-top:var(--dm-s-2);max-width:calc(100% - var(--dm-s-6))}
/* the quiet Agree button beside the time, its glyph on the same right edge as Resolve's */
.dm-cmx-tools{margin-left:auto;margin-right:-2px;display:flex;gap:var(--dm-s-1);transition:opacity var(--dm-t-fast)}
.dm-cmx-tools .dm-ib{width:26px;height:26px;color:var(--dm-muted)}
.dm-cmx-tools .dm-ib[aria-pressed="true"]{color:var(--dm-accent-fg)}
@media (hover:hover) and (pointer:fine){.dm-cmx-tools{opacity:0}}
.dm-cmx-c .dm-n:focus-within .dm-cmx-tools{opacity:1}
@media (hover:hover) and (pointer:fine){.dm-cmx-c:hover .dm-cmx-tools{opacity:1}}
/* how many agreed: a small chip under the text. Hovered it takes a quiet fill; once you have agreed it takes the accent's
   tint with the accent's text, as a reaction of yours does (owner, 20 Nov: hover and selected are a quiet, deeper fill) */
.dm-cmx-rs{display:flex;margin-top:var(--dm-s-2)}
.dm-cmx-rs:has(.dm-cmx-rc[hidden]){display:none}
.dm-cmx-rc{display:inline-flex;align-items:center;gap:var(--dm-s-1);height:22px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-pill);font-size:12px;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);transition:background-color var(--dm-t-fast),box-shadow var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-cmx-rc:hover{background:color-mix(in srgb,var(--dm-fg) 5%,var(--dm-surface))}}
.dm-cmx-rc[aria-pressed="true"]{color:var(--dm-accent-fg);background:var(--dm-accent-bg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark) 25%,transparent)}
@media (hover:hover) and (pointer:fine){.dm-cmx-rc[aria-pressed="true"]:hover{background:linear-gradient(color-mix(in srgb,var(--dm-fg) 4%,transparent),color-mix(in srgb,var(--dm-fg) 4%,transparent)),var(--dm-accent-bg)}}
/* the reply field: a dimmed edge at rest, one step stronger while it has the focus, and no ring. A half-strength hairline
   sets it off from the thread, as one sets the head off (owner, 21 Nov) */
.dm-cmx-in{position:relative;display:grid;grid-template-rows:minmax(0,1fr);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);transition:grid-template-rows var(--dm-t) var(--dm-ease),margin var(--dm-t) var(--dm-ease),padding var(--dm-t) var(--dm-ease),border-width var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease),visibility 0s}
.dm-cmx-box{display:flex;align-items:center;gap:6px;height:var(--dm-field-h);padding:0 5px 0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-cmx-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-cmx-box:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-cmx-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.dm-cmx-box input::placeholder{color:var(--dm-muted)}
.dm-cmx-go{width:30px;height:30px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;flex:none;transition:background var(--dm-t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.dm-cmx-go:hover{background:var(--dm-accent-2)}}
.dm-cmx-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring);transform:none}
@media (hover:hover) and (pointer:fine){.dm-cmx-go[disabled]:hover{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring);transform:none}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink Send alone presses */
.dm-cmx :is(.dm-ib,.dm-pill,.dm-cmx-go,.dm-cmx-rc):active,:root[data-style="clean"] .dm-cmx .dm-ib:active,:root [data-style="clean"] .dm-cmx .dm-ib:active,:root [data-style="clean"].dm-cmx .dm-ib:active{transform:none}
/* the mention list opens upward from the field, over the thread */
.dm-cmx-men{bottom:46px;left:0;min-width:210px;--dm-origin:bottom left}
/* resolved: the thread stays as it is, in full colour (owner, 20 Nov: nothing fades to say it is past), the pin turns green,
   a green Resolved chip says so, and the reply field folds away while the card eases to its new height; Reopen brings it back */
.dm-cmx.dm-done .dm-cmx-in{grid-template-rows:minmax(0,0fr);margin-top:calc(-1 * var(--dm-s-4));padding-top:0;border-top-width:0;opacity:0;overflow:hidden;visibility:hidden;transition:grid-template-rows var(--dm-t) var(--dm-ease),margin var(--dm-t) var(--dm-ease),padding var(--dm-t) var(--dm-ease),border-width var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease),visibility 0s var(--dm-t)}
@media (prefers-reduced-motion:reduce){.dm-cmx-in{transition:none!important}.dm-cmx-rp>.dm-cmx-c::after{animation:none}}
.dm-cmx-st .dm-tag{margin-left:calc(-1 * var(--dm-s-1))}
/* the agent's change applied: a neutral line with the green tick (owner, 18 Nov: a finished state has no green words or fill) */
.dm-cmx-rv{font-size:12.5px;line-height:28px;color:var(--dm-fg2);display:flex;align-items:center;gap:6px}
.dm-cmx-rv svg{color:var(--dm-ok-mark)}
:root:not([data-style="soft"],[data-style="clean"]) .dm-cmx-c .dm-m:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 -1px 0 var(--dm-accent-mark)}
/* Clean: the head is a strip, its controls on the content's 16px column, and the reply field sits in a foot strip that folds
   away with it once the thread is resolved (owner, 21 Nov). Send is the field's own Send (see the Clean section): 5px from
